package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import com.insight.quantlife.*;

/** Creation metadata, date preview, confirmed date-only updates and safe retries. */
public class FeishuDateTest extends FeishuImportTest {
 static final String ID="SyntheticFeishuDocumentA",URL="https://a.feishu.cn/docx/"+ID;
 JSONObject dated(String time)throws Exception{JSONObject p=fixture("创建日期测试正文，不改变内容或学习时长。");p.getJSONObject("data").put("meta_map",new JSONObject().put(ID,new JSONObject().put("create_time",time).put("edit_time","2026-10-27T10:00:00+08:00")));return p;}
 JSONObject stageDate()throws Exception{FeishuImport.stage(getTargetContext(),FeishuImport.parse(dated("2026-03-27T10:07:36.448+08:00"),URL),false);return pending();}
 void parsed()throws Exception{
  JSONObject p=FeishuImport.parse(dated("2026-03-27T10:07:36.448+08:00"),URL);check(p.getString("documentCreatedDate").equals("2026-03-27"),"Use exact document creation day, not last-edit time");check(p.getLong("documentCreatedAt")==1774577256448L,"Retain creation instant with milliseconds");
  p=FeishuImport.parse(dated("2026-03-27T00:07:00+08:00"),URL);check(p.getString("documentCreatedDate").equals("2026-03-27"),"Midnight source date does not shift to previous UTC day");
  for(String value:new String[]{"","not-a-date","2026-02-30T10:00:00+08:00","2099-01-01T00:00:00Z","2026-03-27"})check(!FeishuImport.parse(dated(value),URL).has("documentCreatedDate"),"Reject missing or invalid creation metadata: "+value);
  p=dated("2026-03-27T10:07:36+08:00");p.getJSONObject("data").getJSONObject("meta_map").put("OtherDocument",p.getJSONObject("data").getJSONObject("meta_map").remove(ID));check(!FeishuImport.parse(p,URL).has("documentCreatedDate"),"Do not borrow another document's date");
 }
 @Override public void onStart(){Bundle result=new Bundle();try{
  if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Synthetic tests require an emulator");parsed();
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  JSONArray all=records();for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i),meta=r.optJSONObject("feishuSource");if(meta!=null&&meta.optString("documentId").equals(ID))h.call("applyRecordAction",new JSONObject().put("kind","delete").put("recordId",r.getString("id")).put("expectedVersion",r.getLong("updatedAt")));}
  JSONObject s=stageDate();h.js("FeishuUI.preview("+s.toString()+")");check(h.js("document.querySelector('#feishu-date').value==='2026-03-27'").equals("true"),"New preview defaults to creation date");h.screenshot("feishu-created-date.png");
  h.js("document.querySelector('#feishu-date').value='2026-03-28';document.querySelector('#feishu-minutes').value='28';document.querySelector('#feishu-save').click()");until("document.querySelector('#editor').open && !!document.querySelector('#doc-read') && !document.querySelector('#doc-read').hidden");close();
  JSONObject r=null;all=records();for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optJSONObject("feishuSource")!=null&&all.getJSONObject(i).getJSONObject("feishuSource").optString("documentId").equals(ID))r=all.getJSONObject(i);if(r==null)throw new Exception("Saved test record missing");
  check(r.getString("date").equals("2026-03-28")&&r.getInt("durationMinutes")==28,"Explicit user date override persists with chosen duration");check(r.getJSONObject("feishuSource").getString("documentCreatedDate").equals("2026-03-27"),"Keep original creation date separately as provenance");
  String id=r.getString("id");int count=records().length();s=stageDate();h.js("FeishuUI.preview("+s.toString()+")");check(h.js("document.querySelector('#feishu-date').value==='2026-03-28'&&document.querySelector('#feishu-save').disabled").equals("true"),"Reimport preserves local date and disables no-op save");click("#feishu-use-created");check(h.js("document.querySelector('#feishu-date').value==='2026-03-27'&&!document.querySelector('#feishu-save').disabled").equals("true"),"Use creation-date action explicitly enables date-only update");h.screenshot("feishu-align-date.png");
  JSONObject args=new JSONObject().put("ticket",s.getString("ticket")).put("date","2026-03-27").put("updateDate",true).put("acknowledge",true).put("expectedId",id).put("expectedVersion",r.getLong("updatedAt"));
  click("#feishu-save");until("document.querySelector('#editor').open && !!document.querySelector('#doc-read') && !document.querySelector('#doc-read').hidden");r=record(id);check(records().length()==count&&r.getString("date").equals("2026-03-27")&&r.getInt("durationMinutes")==28&&r.getString("note").equals(s.getString("note")),"Date-only save changes date without duplicating or rewriting body/time");close();
  // A lost-reply retry is tested with a retained ticket using a direct bridge request.
  s=stageDate();args.put("ticket",s.getString("ticket")).put("date","2026-03-26").put("expectedVersion",r.getLong("updatedAt"));h.call("feishuCommit",args);check(((JSONObject)h.call("feishuCommit",args)).getBoolean("unchanged"),"Date-only lost-reply retry is idempotent");
  r=record(id);s=stageDate();args.put("ticket",s.getString("ticket")).put("date","2026-03-25").put("expectedVersion",r.getLong("updatedAt"));r.put("durationMinutes",35);h.call("saveDocument",new JSONObject().put("record",r).put("allowDuplicate",true).put("expectedVersion",r.getLong("updatedAt")));boolean stale=false;try{h.call("feishuCommit",args);}catch(Exception ex){stale=true;}check(stale&&record(id).getString("date").equals("2026-03-26")&&record(id).getInt("durationMinutes")==35,"Stale date request cannot overwrite a concurrent local edit");
  stage("无创建日期的笔记");s=pending();h.js("FeishuUI.preview("+s.toString()+")"); // Same bridge preview path as real imports, including local-record lookup.
  check(h.js("document.querySelector('#feishu-date').value==='2026-03-26'").equals("true"),"Missing metadata does not reset an existing date to today");h.js("FeishuUI.close();FeishuUI.preview({..."+s.toString()+",existing:null,unchanged:false})");check(h.js("document.querySelector('#feishu-date').value===''").equals("true"),"Unknown new-document creation date stays blank, not silently today");click("#feishu-save");check(h.js("!document.querySelector('#feishu-error').hidden&&document.querySelector('#feishu-error').textContent.includes('有效日期')").equals("true"),"Missing creation date requires explicit date before saving");h.js("FeishuUI.close()");FeishuImport.clear(getTargetContext(),s.getString("ticket"));
  result.putString("stream","PASS FeishuDateTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){result.putString("stream","FAIL FeishuDateTest after "+passed+": "+ex+"\n"+android.util.Log.getStackTraceString(ex));finish(Activity.RESULT_CANCELED,result);}}
}
